#include <stdio.h>
int m[4][4] = {
    {1,1,0,0},
    {1,1,0,0},
    {0,0,1,1},
    {0,0,1,1}
};  /* 两个等价块 {0,1} 与 {2,3} */
int main(void){
    int n=4, ref=1, sym=1, trans=1;
    for (int i=0;i<n;i++) if (!m[i][i]) ref=0;
    for (int i=0;i<n;i++) for (int j=0;j<n;j++) if (m[i][j]!=m[j][i]) sym=0;
    for (int i=0;i<n;i++) for (int j=0;j<n;j++) if (m[i][j])
        for (int k=0;k<n;k++) if (m[j][k] && !m[i][k]) trans=0;
    printf("reflexive=%d symmetric=%d transitive=%d equivalence=%d\n",
           ref, sym, trans, ref&&sym&&trans);
    return 0;
}
